import { toolCallErrorMessage } from "../tool-result.js";
import { isRecord } from "../is-record.js";
const MAX_SCANNED_CHARS = 2_000;
const TEXT_CLASSES = [
    ["not_found", /\bnot found: \/|path does not exist:|\benoent\b|no such file or directory/i],
    [
        "rate_limited",
        /\b(?:HTTP(?:\/[\d.]+)?|status(?: code)?|code)[\s:=]*429\b|rate limit|too many requests/i,
    ],
    ["timeout", /\btimed?\s*out\b|\btimeout\b|\betimedout\b/i],
    [
        "unauthorized",
        /\b(?:HTTP(?:\/[\d.]+)?|status(?: code)?|code)[\s:=]*(?:401|403)\b|\bunauthorized\b|\bforbidden\b/i,
    ],
];
function errorText(output) {
    const message = toolCallErrorMessage(output);
    if (message !== undefined || output === null || typeof output !== "object") {
        return message;
    }
    if (!isRecord(output)) {
        return undefined;
    }
    const error = output.error;
    return typeof error === "string" && error.trim() !== "" ? error : undefined;
}
const HOST_TOOL_PREFIX = /^Tool "[^"]*" /;
const INPUT_ECHO_PREFIX = /^(?:Invalid input for tool "|invalid grep pattern:)/i;
export function classifyToolErrorText(output) {
    const text = errorText(output)?.replace(HOST_TOOL_PREFIX, "").slice(0, MAX_SCANNED_CHARS);
    if (text === undefined || INPUT_ECHO_PREFIX.test(text)) {
        return "tool_error";
    }
    for (const [errorClass, pattern] of TEXT_CLASSES) {
        if (pattern.test(text)) {
            return errorClass;
        }
    }
    return "tool_error";
}
